_UNITS = [("TiB", 1024 ** 4), ("GiB", 1024 ** 3), ("MiB", 1024 ** 2), ("KiB", 1024)]


def format_size(n):
    if n < 1024:
        return "%d B" % n
    for name, size in _UNITS:
        if n >= size:
            tenths = (n * 10) // size
            return "%d.%d %s" % (tenths // 10, tenths % 10, name)
    raise AssertionError("unreachable")

_UNITS = (("TiB", 1 << 40), ("GiB", 1 << 30), ("MiB", 1 << 20), ("KiB", 1 << 10))


def format_size(n):
    if n < 1024:
        return str(n) + " B"
    for name, size in _UNITS:
        if n >= size:
            tenths = (n * 10 + size // 2) // size
            whole, frac = divmod(tenths, 10)
            return "{}.{} {}".format(whole, frac, name)
    raise AssertionError("unreachable")

UNITS = [("KiB", 2 ** 10), ("MiB", 2 ** 20), ("GiB", 2 ** 30), ("TiB", 2 ** 40)]


def format_size(n):
    if n < 1024:
        return f"{n} B"
    unit, size = UNITS[0]
    for candidate_unit, candidate_size in UNITS:
        if n >= candidate_size:
            unit, size = candidate_unit, candidate_size
    tenths = (2 * n * 10 + size) // (2 * size)
    return f"{tenths // 10}.{tenths % 10} {unit}"

