features = []
fixes = []
with open("commits.txt", encoding="utf-8") as fh:
    for line in fh.read().splitlines():
        head, sep, description = line.partition(": ")
        if not sep:
            continue
        if head.endswith("!"):
            head = head[:-1]
        kind = head.split("(", 1)[0]
        if kind == "feat":
            features.append(description)
        elif kind == "fix":
            fixes.append(description)

parts = []
if features:
    parts.append("\n## Features\n" + "\n".join("- " + d for d in features) + "\n")
if fixes:
    parts.append("\n## Fixes\n" + "\n".join("- " + d for d in fixes) + "\n")
with open("CHANGELOG.md", "w", encoding="utf-8") as fh:
    fh.write("".join(parts))

