def _upper(ch):
    return "A" <= ch <= "Z"


def _lower_or_digit(ch):
    return "a" <= ch <= "z" or "0" <= ch <= "9"


def to_snake(name):
    out = []
    for i, ch in enumerate(name):
        if i > 0 and _upper(ch):
            prev = name[i - 1]
            if _lower_or_digit(prev):
                out.append("_")
        out.append(ch.lower())
    return "".join(out)

import re

_BOUNDARY = re.compile(r"(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])")


def to_snake(name):
    return _BOUNDARY.sub("_", name).lower()

def to_snake(name):
    padded = " " + name + " "
    pieces = []
    for i in range(1, len(padded) - 1):
        prev, ch, nxt = padded[i - 1], padded[i], padded[i + 1]
        if i > 1 and ch.isupper():
            if prev.islower() or prev.isdigit():
                pieces.append("_")
            elif prev.isupper() and nxt.islower():
                pieces.append("_")
        pieces.append(ch)
    return "".join(pieces).lower()
